# One-round test where clients also train on images generated by the global model, weighted per band, 2k FID.
import argparse
import json
import os
import sys
from copy import deepcopy

import torch
from torchmetrics.image.fid import FrechetInceptionDistance

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))

from data import load_cifar10, load_partition, partition_path
from diffusion import Schedule, denoising_loss
from common import cos, flat, run_steps, setflat
from fisher_merge import band_loss
from model import UNet
from sample import generate


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--ckpt", required=True)
    parser.add_argument("--out", default="runs/one_round/self_replay")
    parser.add_argument("--alpha", default="class")
    parser.add_argument("--n_clients", type=int, default=10)
    parser.add_argument("--seed", type=int, default=0)
    parser.add_argument("--local_epochs", type=int, default=5)
    parser.add_argument("--batch_size", type=int, default=128)
    parser.add_argument("--lr", type=float, default=2e-4)
    parser.add_argument("--n_replay", type=int, default=1000)
    parser.add_argument("--replay_batch", type=int, default=32)
    parser.add_argument("--schedules", nargs="+", default=["1,1,1,1,1", "1,1,0.5,0.25,0.25", "0,0,1,1,1"])
    parser.add_argument("--n_eval", type=int, default=2048)
    parser.add_argument("--fid_n", type=int, default=2000)
    parser.add_argument("--data_root", default="./data")
    parser.add_argument("--partition_dir", default="./partitions")
    args = parser.parse_args()

    os.makedirs(os.path.dirname(args.out), exist_ok=True)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    use_amp = device.type == "cuda"
    x_all, _ = load_cifar10(args.data_root)
    x_all = x_all.to(device)
    x_test, _ = load_cifar10(args.data_root, train=False)
    sched = Schedule(device=device)
    parts = [torch.from_numpy(p).to(device) for p in load_partition(partition_path(args.partition_dir, args.n_clients, args.alpha, args.seed))]
    sizes = torch.tensor([len(p) for p in parts], dtype=torch.float)
    pi = (sizes / sizes.sum()).tolist()
    bands = [(200 * b, 200 * b + 200) for b in range(5)]

    model = UNet("small").to(device)
    model.load_state_dict(torch.load(args.ckpt, map_location=device))
    w0 = flat(model)
    work = deepcopy(model)

    replay = generate(model.eval(), args.n_replay, sched, device, seed=777) * 2 - 1
    print(f"generated {len(replay)} replay images", flush=True)

    eg = torch.Generator(device=device).manual_seed(404)
    xe = x_test[torch.randperm(len(x_test), generator=torch.Generator().manual_seed(404))[:args.n_replay]].to(device)
    t_list = [torch.randint(lo, hi, (args.n_replay,), device=device, generator=eg) for lo, hi in bands]
    eps_e = torch.randn(xe.shape, device=device, generator=eg)
    real_loss = band_loss(work, w0, xe, t_list, eps_e, sched)
    syn_loss = band_loss(work, w0, replay, t_list, eps_e, sched)
    gap = [s / r - 1 for s, r in zip(syn_loss, real_loss)]
    print("denoising loss of global model, real vs its own samples, by band: " +
          " | ".join(f"{lo}-{hi}: {r:.5f} vs {s:.5f} ({g:+.1%})" for (lo, hi), r, s, g in zip(bands, real_loss, syn_loss, gap)), flush=True)

    gen = torch.Generator(device=device).manual_seed(11)
    sch = []
    for idx in parts:
        b = []
        for _ in range(args.local_epochs):
            perm = idx[torch.randperm(len(idx), device=device, generator=gen)]
            b += [perm[i:i + args.batch_size] for i in range(0, len(perm), args.batch_size)]
        sch.append(b)

    def own(i, k):
        idx = sch[i][k]
        g = torch.Generator(device=device).manual_seed(11 * 1000003 + i * 10007 + k)
        t = torch.randint(0, sched.T, (len(idx),), device=device, generator=g)
        eps = torch.randn((len(idx), 3, 32, 32), device=device, generator=g)
        flip = torch.rand(len(idx), device=device, generator=g) < 0.5
        return torch.where(flip.view(-1, 1, 1, 1), x_all[idx].flip(3), x_all[idx]), t, eps

    def client_loss(i, wts):
        def f(m, k):
            x0, t, eps = own(i, k)
            if wts is not None:
                g = torch.Generator(device=device).manual_seed(55 * 1000003 + i * 10007 + k)
                n = args.replay_batch
                xr = replay[torch.randint(0, len(replay), (n,), device=device, generator=g)]
                flip = torch.rand(n, device=device, generator=g) < 0.5
                xr = torch.where(flip.view(-1, 1, 1, 1), xr.flip(3), xr)
                band = torch.multinomial(wts, n, replacement=True, generator=g)
                tr = band * 200 + torch.randint(0, 200, (n,), device=device, generator=g)
                er = torch.randn((n, 3, 32, 32), device=device, generator=g)
                x0, t, eps = torch.cat([x0, xr]), torch.cat([t, tr]), torch.cat([eps, er])
            return denoising_loss(m, x0, t, eps, sched)
        return f

    variants = [("fedavg", None)] + [(f"replay_{s}", torch.tensor([float(v) for v in s.split(",")], device=device)) for s in args.schedules]
    if args.fid_n:
        fid = FrechetInceptionDistance(feature=2048, normalize=True, reset_real_features=False).to(device)
        for i in range(0, len(x_all), 1000):
            fid.update((x_all[i:i + 1000] + 1) / 2, real=True)

    xh = x_test[torch.randperm(len(x_test), generator=torch.Generator().manual_seed(505))[:args.n_eval]].to(device)
    th = [torch.randint(lo, hi, (args.n_eval,), device=device, generator=eg) for lo, hi in bands]
    eh = torch.randn(xh.shape, device=device, generator=eg)
    res = {"real_loss": real_loss, "synthetic_loss": syn_loss, "relative_gap": gap, "models": {}}
    for name, rng in variants:
        deltas = [run_steps(work, w0, len(sch[i]), client_loss(i, rng), args.lr, "adam", use_amp, 1.0)[0] for i in range(len(parts))]
        u = sum(p * d for p, d in zip(pi, deltas))
        losses = band_loss(work, w0 + u, xh, th, eh, sched)
        r = {"band_loss": losses, "norm_update": u.norm().item(), "fid": float("nan")}
        if args.fid_n:
            setflat(work, w0 + u)
            fid.reset()
            for j in range(0, args.fid_n, 1000):
                fid.update(generate(work.eval(), min(1000, args.fid_n - j), sched, device, seed=j), real=False)
            r["fid"] = fid.compute().item()
        res["models"][name] = r
        print(f"{name:18s} | loss by band {' '.join(f'{v:.5f}' for v in losses)} | |u| {r['norm_update']:.3f} | FID{args.fid_n} {r['fid']:.2f}", flush=True)
        json.dump(res, open(args.out + ".json", "w"), indent=1)


if __name__ == "__main__":
    main()
